(function(){
"use strict";
var q=new URLSearchParams(location.search),view=q.get("view")||"home",instanceId=q.get("instance")||"",decisionEvent="";
var body=document.getElementById("pageBody"),titles={home:"审批工作台",pending:"待办审批",done:"已办事项",all:"全部实例",detail:"审批详情"};
var statusClass={"审批中":"pending","已批准":"approved","驳回起草人":"returned","已拒绝":"rejected","已撤销":"revoked","已终止":"terminated"};
var eventNames={returned:"驳回起草人",approved:"批准",rejected:"拒绝",revoked:"撤销",terminated:"终止"};

function esc(v){return String(v==null?"":v).replace(/[&<>"']/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c];});}
function tag(s){return '<span class="tag '+(statusClass[s]||"revoked")+'">'+esc(s||"-")+'</span>';}
function businessName(){return "集团监督检查";}
function all(){return OABridge.read().instances.slice().sort(function(a,b){return String(b.updatedAt).localeCompare(String(a.updatedAt));});}
function activateNav(){document.querySelectorAll("[data-nav]").forEach(function(a){a.classList.toggle("active",a.dataset.nav===(view==="detail"?"all":view));});document.getElementById("pendingCount").textContent=all().filter(function(x){return x.status==="审批中";}).length;}
function head(title,crumb){document.getElementById("pageTitle").textContent=title;document.getElementById("breadcrumb").textContent=crumb||"统一办公平台 / 审批中心";}
function rows(list){if(!list.length)return '<div class="empty">当前没有符合条件的审批实例</div>';return '<div class="table-wrap"><table class="data-table"><thead><tr><th>实例号</th><th>业务类型</th><th>业务标题</th><th>申请人 / 组织</th><th>提交时间</th><th>状态</th><th>操作</th></tr></thead><tbody>'+list.map(function(x){return '<tr><td>'+esc(x.instanceId)+'</td><td>'+esc(businessName(x))+'</td><td class="title-cell"><b>'+esc(x.title||x.businessCode)+'</b><small>'+esc(x.businessCode||x.businessId)+'</small></td><td class="title-cell"><b>'+esc(x.applicant||"-")+'</b><small>'+esc(x.applicantOrg||"-")+'</small></td><td>'+esc(x.updatedAt||x.submittedAt||"-")+'</td><td>'+tag(x.status)+'</td><td><button class="btn text" onclick="openDetail(\''+encodeURIComponent(x.instanceId)+'\')">'+(x.status==="审批中"?"办理":"查看")+'</button></td></tr>';}).join("")+'</tbody></table></div>';}
function listPanel(title,list,more){return '<section class="panel"><div class="panel-head"><h2>'+title+'</h2>'+(more?'<a class="btn text" href="?view='+more+'">查看全部 →</a>':'')+'</div>'+rows(list)+'</section>';}
function renderHome(){var list=all(),pending=list.filter(function(x){return x.status==="审批中";}),done=list.filter(function(x){return x.status!=="审批中";}),returned=list.filter(function(x){return x.status==="驳回起草人";});head("审批工作台");body.innerHTML='<div class="metric-grid"><div class="metric"><label>我的待办</label><b>'+pending.length+'</b><small>等待当前用户处理</small></div><div class="metric green"><label>今日已办</label><b>'+done.length+'</b><small>演示数据口径</small></div><div class="metric warn"><label>驳回起草人</label><b>'+returned.length+'</b><small>等待安全平台修改</small></div><div class="metric gray"><label>全部实例</label><b>'+list.length+'</b><small>安全管理平台来源</small></div></div>'+listPanel("最近待办",pending.slice(0,6),"pending");}
function renderList(kind){var list=all().filter(function(x){return x.businessType==="supervision";}),title=titles[kind];if(kind==="pending")list=list.filter(function(x){return x.status==="审批中";});if(kind==="done")list=list.filter(function(x){return x.status!=="审批中";});head(title);body.innerHTML='<section class="panel"><div class="panel-head"><h2>'+title+'</h2><span>'+list.length+' 条</span></div><div class="panel-body"><div class="filters"><input id="keyword" placeholder="搜索实例号、标题、业务编号"><select id="typeFilter"><option value="supervision">集团监督检查</option></select><button class="btn primary" onclick="filterList(\''+kind+'\')">查询</button></div><div id="listRows">'+rows(list)+'</div></div></section>';}
function importFromOpener(){if(!instanceId||!window.opener||window.opener.closed)return;try{var source=window.opener.OABridge&&window.opener.OABridge.byInstance(instanceId),local=OABridge.byInstance(instanceId);if(source&&(!local||(source.status==="审批中"&&local.status!=="审批中")))OABridge.submit(source);}catch(e){}}
function detail(){importFromOpener();var x=OABridge.byInstance(instanceId);head("审批详情","统一办公平台 / 审批中心 / "+(x?x.instanceId:"实例不存在"));if(!x){body.innerHTML='<section class="panel"><div class="empty">未找到审批实例。请从安全管理平台的“审批中”入口重新打开。</div></section>';return;}var snapshot=x.summary||{},materials=x.materials||[],history=x.history||[];body.innerHTML='<section class="panel"><div class="detail-hero"><div><span>'+tag(x.status)+'</span><h2>'+esc(x.title||x.businessCode)+'</h2><p>'+esc(x.instanceId)+' · '+esc(businessName(x))+'</p></div><div class="hero-actions"><button class="btn ghost" onclick="openSafety(\''+encodeURIComponent(x.instanceId)+'\')">查看安全管理平台业务单</button></div></div></section><div class="detail-grid"><div><section class="panel" style="margin-top:0"><div class="panel-head"><h2>申请信息</h2></div><div class="panel-body"><div class="flow-note">OA 展示完整审批过程；安全管理平台仅展示“审批中”并提供本页链接。</div><div class="info-grid" style="margin-top:14px"><div class="info-item"><span>来源系统</span><b>'+esc(x.sourceSystem||"安全管理平台")+'</b></div><div class="info-item"><span>业务编号</span><b>'+esc(x.businessCode||x.businessId)+'</b></div><div class="info-item"><span>申请人</span><b>'+esc(x.applicant||"-")+'</b></div><div class="info-item"><span>申请组织</span><b>'+esc(x.applicantOrg||"-")+'</b></div><div class="info-item"><span>审批层级</span><b>'+esc(x.currentNode||"-")+'</b></div><div class="info-item"><span>提交时间</span><b>'+esc(x.updatedAt||x.createdAt||"-")+'</b></div></div><h3>业务快照</h3><div class="snapshot">'+Object.keys(snapshot).map(function(k){return '<div class="snapshot-item"><span>'+esc(({location:"位置",description:"事实描述",source:"来源",version:"风险版本",level:"最高风险等级",hazardCount:"危险源数量",measureCount:"管控措施数量"}[k]||k))+'</span><b>'+esc(snapshot[k])+'</b></div>';}).join("")+'</div><h3>审批材料</h3><ul class="material-list">'+materials.map(function(m){return '<li>'+esc(m)+'</li>';}).join("")+'</ul>'+(x.status==="审批中"?'<div class="decision-bar"><button class="btn danger" onclick="openDecision(\'returned\')">驳回起草人</button><button class="btn success" onclick="openDecision(\'approved\')">批准</button><button class="btn danger" onclick="openDecision(\'rejected\')">拒绝</button><button class="btn warn" onclick="openDecision(\'revoked\')">撤销</button><button class="btn ghost" onclick="openDecision(\'terminated\')">终止</button></div>':'')+'</div></section></div><aside><section class="panel" style="margin-top:0"><div class="panel-head"><h2>审批过程</h2></div><div class="panel-body"><ul class="timeline">'+history.map(function(h){return '<li><b>'+esc(h.action)+'</b><small>'+esc(h.by)+' · '+esc(h.at)+'</small><div>'+esc(h.note||"")+'</div></li>';}).join("")+'</ul></div></section></aside></div>';}
function render(){activateNav();if(view==="detail")detail();else if(view==="home")renderHome();else renderList(view);}
function directCallback(event,note,payload){if(!window.opener||window.opener.closed)return false;try{if(current().businessType==="supervision"&&typeof window.opener.receiveOaHazardEvent==="function")return !!window.opener.receiveOaHazardEvent(current().businessId,event,note,payload).ok;}catch(e){}return false;}
function current(){return OABridge.byInstance(instanceId);}
function toast(message,error){var el=document.getElementById("toast");el.textContent=message;el.className="toast show"+(error?" error":"");clearTimeout(toast.timer);toast.timer=setTimeout(function(){el.className="toast";},2600);}

window.openDetail=function(id){location.href="?view=detail&instance="+id;};
window.filterList=function(kind){var key=document.getElementById("keyword").value.trim().toLowerCase(),type=document.getElementById("typeFilter").value,list=all();if(kind==="pending")list=list.filter(function(x){return x.status==="审批中";});if(kind==="done")list=list.filter(function(x){return x.status!=="审批中";});list=list.filter(function(x){return (!type||x.businessType===type)&&(!key||[x.instanceId,x.title,x.businessCode,x.businessId].join(" ").toLowerCase().indexOf(key)>-1);});document.getElementById("listRows").innerHTML=rows(list);};
window.openSafety=function(id){var x=OABridge.byInstance(decodeURIComponent(id));if(!x||!x.safetyUrl){toast("安全管理平台未返回业务单链接",true);return;}window.open(x.safetyUrl,"safety_business_"+x.businessId);};
window.openDecision=function(event){var x=current();if(!x||x.status!=="审批中")return;decisionEvent=event;document.getElementById("decisionTitle").textContent=eventNames[event];document.getElementById("decisionSummary").textContent=x.businessCode+" · "+x.title;document.getElementById("decisionNote").value="";document.getElementById("noteRequired").textContent=(event==="returned"||event==="rejected")?"*":"";document.getElementById("assessmentFields").hidden=!(x.businessType==="supervision"&&event==="approved");document.getElementById("confirmDecision").textContent="确认"+eventNames[event];document.getElementById("decisionMask").hidden=false;};
window.closeDecision=function(){document.getElementById("decisionMask").hidden=true;decisionEvent="";};
window.confirmDecision=function(){var x=current(),note=document.getElementById("decisionNote").value.trim();if(!x||!decisionEvent)return;if((decisionEvent==="returned"||decisionEvent==="rejected")&&!note){toast("请填写处理意见",true);return;}var payload={};if(x.businessType==="supervision"&&decisionEvent==="approved"){var person=document.getElementById("assessmentResponsible"),option=person.options[person.selectedIndex];payload.assessmentResponsiblePersonId=person.value;payload.assessmentResponsible=option&&option.getAttribute("data-name")||"";payload.penaltyAmount=Number(document.getElementById("penaltyAmount").value);if(!payload.assessmentResponsiblePersonId||!payload.assessmentResponsible||!Number.isFinite(payload.penaltyAmount)||payload.penaltyAmount<0){toast("请选择考核责任人并填写正确的考核金额",true);return;}}note=note||("OA "+eventNames[decisionEvent]);var event=decisionEvent,result=OABridge.decision(x.instanceId,event,note,payload,"OA审批人（演示）");if(!result.ok){toast(result.msg,true);return;}if(directCallback(event,note,payload))OABridge.acknowledge(result.callback.id);closeDecision();toast("已处理并向安全管理平台回传："+eventNames[event]);render();};
window.resetDemo=function(){OABridge.reset();view="home";history.replaceState(null,"","?view=home");render();toast("已恢复 OA 演示数据");};
window.addEventListener("storage",render);window.addEventListener("oa-bridge-change",function(){if(!document.getElementById("decisionMask")||document.getElementById("decisionMask").hidden)render();});
render();
})();
